// Offline support for levy-platform.com/amirnet (generated by build.py — edit sw.template.js)
const CACHE = "amirnet-76bd3c2af5";
const ASSETS = ["./", "manifest.webmanifest", "extra.json", "keys.json", "lessons.json", "rsrc.json", "sc.json", "updates.json", "vocab.json", "icons/apple-touch-icon.png", "icons/icon-192.png", "icons/icon-512.png", "icons/maskable-512.png"];
self.addEventListener("install", e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(ASSETS)).then(() => self.skipWaiting()));
});
self.addEventListener("activate", e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith("amirnet-") && k !== CACHE).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener("fetch", e => {
  const req = e.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  // never cache Firebase auth / database traffic
  if (/googleapis\.com|firebaseio|identitytoolkit|securetoken/.test(url.host)) return;
  const sameOrigin = url.origin === location.origin;
  // pages: network first so new versions arrive, cache as offline fallback
  if (req.mode === "navigate") {
    e.respondWith(fetch(req).then(r => { const c = r.clone(); caches.open(CACHE).then(x => x.put("./", c)); return r; }).catch(() => caches.match("./")));
    return;
  }
  // our content + fonts + Firebase SDK: cache first, refresh in the background
  if (sameOrigin || /fonts\.(googleapis|gstatic)\.com|www\.gstatic\.com/.test(url.host)) {
    e.respondWith(caches.match(req).then(hit => {
      const net = fetch(req).then(r => { if (r.ok || r.type === "opaque") { const c = r.clone(); caches.open(CACHE).then(x => x.put(req, c)); } return r; }).catch(() => hit);
      return hit || net;
    }));
  }
});
